G=load(); print(sorted(G))
for num in ('1','2','3'):
    I=G[f'Demo pair {num} input']; O=G[f'Demo pair {num} output']
    H,W=len(I),len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    # original cells per color
    orig=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg: orig[I[r][c]].append((r,c))
    # added cells
    add=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if I[r][c]==bg and O[r][c]!=bg: add[O[r][c]].append((r,c))
    # for each added cell, distance to nearest same-color original cell
    from collections import deque
    def dist(cell,color):
        sr,sc=cell; best=10**9
        q=deque([(sr,sc,0)]); seen={(sr,sc)}
        while q:
            y,x,d=q.popleft()
            if y==sr and x==sc: best=min(best,d); break
            if I[y][x]==color: return best-d
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen:
                    seen.add((ny,nx)); q.append((ny,nx,d+1))
        return None
    print(f'--- demo {num} bg={bg}---')
    for col in sorted(orig):
        ds=[]
        for p in add.get(col,[]):
            d=dist(p,col)
            if d is not None: ds.append(('added-'+str(col),'orig',p,I[p[0]][p[1]],d))
        print(' color',col,'n_add',len(add[col]),ds[:5])

