from collections import defaultdict
def extract(pair):
    I=G[pair+' input'];O=G[pair+' output']
    H=len(I);W=len(I[0])
    bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    S=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=bg]
    m=defaultdict(lambda: defaultdict(list))
    for r in range(H):
        for c in range(W):
            if I[r][c]==bg and O[r][c]!=bg:
