# For each seed, for each template color != seed color, for each orientation (try all dihedral), try all offsets s.t. exactly N cells change in output
def dihedral(shp):
    res=[]
    cur=list(shp)
    for _ in range(2):
        for _ in range(4):
            res.append(tuple(sorted(cur)))
            mx=max(q[1] for q,v in cur); cur=[((q[0],mx-q[1]),v) for q,v in cur]
        my=max(q[0] for q,v in cur); cur=[((my-q[0],q[1]),v) for q,v in cur]
    out={}
    for shp2 in res:
        out.setdefault(normshp(None,shp2),[]).append(shp2)
    return list(out.values())
