def dihedral(ts):
    res=[]
    cur=[list(p) for p in ts]   # cells with colors
    for _ in range(2):
        for _ in range(4):
            n0=min(q[0] for q,v in cur); n1=min(q[1] for q,v in cur)
            res.append(tuple(sorted(((q[0]-n0,q[1]-n1),v) for q,v in cur)))
            mx=max(q[1] for q,v in cur)
            cur=[((q[0],mx-q[1]),v) for q,v in cur]
        my=max(q[0] for q,v in cur)
        cur=[((my-q[0],q[1]),v) for q,v in cur]
    return sorted(set(res))
