    return G
G=load()

def comps(A,H,W,bg):
    seen=set();out=[]
    for y in range(H):
        for x in range(W):
            c=A[y][x]
            if c==bg or (y,x) in seen: continue
            stack=[(y,x)];cells=[]
            while stack:
                cy,cx=stack.pop()
                if (cy,cx) in seen or A[cy][cx]!=c: continue
                seen.add((cy,cx));cells.append((cy,cx))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W: stack.append((ny,nx))
            out.append((c,frozenset(cells)))
    return out

def solve(A):
    H,W=len(A),len(A[0])
    bg=Counter(v for r in A for v in r).most_common(1)[0][0]
    ca=comps(A,H,W,bg)
    tmpl=max([cl for c,cl in ca if len(cl)>1], key=len)
    tc=tuple(sorted(tmpl))
    marks=[(y,x) for y in range(H) for x in range(W) if A[y][x]!=bg and not any(c==A[y][x] and p==(y,x) for c,p in ca if len(p)>1)]
    # find rel offset: marker cell = tl + rel ; shape ts = norm(tmpl)
    ys=[p[0] for p in ts_:=frozenset((p[0]-min(q[0] for q in tmpl),p[1]-min(q[1] for q in tmpl)) for p in tmpl)]
    xs=[p[1] for p in ts_]
    sy,sx=min(ys),min(xs)
    ts=frozenset((y-sy,x-sx) for y,x in tmpl)
    h=max(p[0] for p in ts); w=max(p[1] for p in ts)
    out=[r[:] for r in A]
    ok_any=False
    for (y,x) in marks:
        found=None
        for rel in ts:
            ty,tx=y-rel[0],x-rel[1]
            if all(0<=ty+p[0]<H and 0<=tx+p[1]<W and A[ty+p[0]][tx+p[1]]==bg for p in ts):
                found=(rel,(ty,tx));break
        if found:
            found=found[1]; ok_any=True
        else:
            # try allowing overlap with other stamps
            best=None
            for rel in ts:
                ty,tx=y-rel[0],x-rel[1]
                if all(0<=ty+p[0]<H and 0<=tx+p[1]<W for p in ts):
                    best=best or rel
            if best: ty,tx=y-best[0],x-best[1]
        if found is None: print('no placement for marker',(y,x))
        else:
            for p in ts:
                cy,cx=ty+p[0],tx+p[1]
                if out[cy][cx]==bg: out[cy][cx]=tc
    return out,ok_any

for n in [6,7,8]:
    A=G[f'Demo pair {n} input'];B=G[f'Demo pair {n} output']
    r,ok=solve(A)
    print(n,ok,'match:',r==B)

