    marks=[(y,x) for y in range(H) for x in range(W) if A[y][x]!=bg and not any(p==(y,x) for c,p in ca if len(p)>1)]
    st_col=ca[[1 if cl is tmpl else 0 for cl,_ in ca]].index(1)+1
    tc=ca[[p==(y,x) for p in [cl]]] 
    print('DEBUG' if False else '', 'stamp_color sample:', [c for c,cl in ca if cl is tmpl][0])
    out=[r[:] for r in A]
    stamp_col=None
    for c,cl in ca:
        if cl is tmpl: stamp_col=c
    ok_any=False
    for (y,x) in marks:
        best=None
        for rel in ts:
            ty,tx=y-rel[0],x-rel[1]
            if all(0<=ty+p[0]<H and 0<=tx+p[1]<W for p in ts):
                # prefer placement with no overlap on non-bg in INPUT
                cells=[(ty+p[0],tx+p[1]) for p in ts]
                if all(A[cy][cx]==bg for cy,cx in cells):
                    return out,ok_any,'exact-bg-placement exists'
                best=rel
        if best is None:
            if verbose: print('no in-bounds placement for marker',(y,x))
            continue
        rel=best; ty,tx=y-best[0],x-best[1]
        ok_any=True
        for p in ts:
            cy,cx=ty+p[0],tx+p[1]
            if out[cy][cx]==bg: out[cy][cx]=stamp_col
    return out,ok_any

for n in [6,7,8]:
    A=G[f'Demo pair {n} input'];B=G[f'Demo pair {n} output']
    try:
        r,ok,info=solve(A)
    except Exception as e:
        r,ok,info=None,e,None
        print(n,'err',e);continue
    print(n,'match:',r==B, ok, info)

