import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def comps(A,H,W,bg):
    seen=set();out=[]
    for y in range(H):
        for x in range(W):
            c=A[y][x]
            if c==bg or (y,x) in seen: continue
            stack=[(y,x)];cells=[]
            while stack:
                cy,cx=stack.pop()
                if (cy,cx) in seen or A[cy][cx]!=c: continue
                seen.add((cy,cx));cells.append((cy,cx))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W: stack.append((ny,nx))
            out.append((c,frozenset(cells)))
    return out

def occ(B,H,W,ts,color):
    # all placements of ts (normalized) in B with color at all cells
    res={}
    ys=[p[0] for p in ts];xs=[p[1] for p in ts]
    sy,sx=min(ys),min(xs)
    for ty in range(H):
        for tx in range(W):
            if all(0<=ty+p[0]-sy<H and 0<=tx+p[1]-sx<W and B[ty+p[0]-sy][tx+p[1]-sx]==color for p in ts):
                res[(ty-sy,tx-sx)]+=1
    return res

for n in [6,7,8]:
    A=G[f'Demo pair {n} input'];B=G[f'Demo pair {n} output']
    H,W=len(A),len(A[0])
    ca=comps(A,H,W,Counter(v for r in A for v in r).most_common(1)[0][0])
    templates=[(c,frozenset(cl)) for c,cl in ca if len(cl)>1]
    print('=== demo',n,'templates:')
    for c,cl in templates:
        ys=[p[0] for p in cl];xs=[p[1] for p in cl]
        sy,sx=min(ys),min(xs)
        norm=frozenset((y-sy,x-sx) for y,x in cl)
        print(' color',c,'norm',sorted(norm),'count in input',sum(1 for c2,cl2 in ca if cl2==frozenset((y+sy,x+sx) for y,x in norm)))
    for c,cl in templates:
        norm=frozenset((y-min(p[0] for p in cl),x-min(p[1] for p in cl)) for y,x in cl)
        print('   occ offsets in output:',dict(occ(B,H,W,norm,c)))
